# 路径穿越防护示例
safe_join() {
  local base="$1" rel="$2"
  local full
  full="$(realpath -m -- "$base/$rel")"
  case "$full" in
    "$base"/*) printf '%s' "$full" ;;
    *) echo "非法路径：$rel" >&2; return 1 ;;
  esac
}

